// Validates the request of the dispatcher and builds the GraphQL query of the PR facts.
JSON.stringify((function () {
    const parse = (x) => (typeof x === 'string' && x ? JSON.parse(x) : (x || null));
    const d = parse($data.data) || {};
    const pr = (/^https:\/\/github\.com\/Appmixer-ai\/appmixer-connectors\/pull\/(\d{1,7})$/.exec(d.pr_url || '') || [])[1];
    const target = /^Appmixer-ai\/([A-Za-z0-9_.-]+)#(\d{1,7})$/.exec(d.target || '');
    const ok = pr && target && /^PVTI_[\w-]+$/.test(d.item_node_id || '') && /^PVT_[\w-]+$/.test(d.project_node_id || '')
        && /^PVTSSF_[\w-]+$/.test(d.status_field_id || '');
    if (!ok) return { ok: false, reason: 'malformed request' };
    const query = 'query {'
        + ' pr: repository(owner: "Appmixer-ai", name: "appmixer-connectors") { pullRequest(number: ' + pr + ') {'
        + ' number url title state isDraft mergeable mergeStateStatus baseRefName headRefOid author { login }'
        + ' closingIssuesReferences(first: 10) { nodes { number repository { nameWithOwner } } }'
        + ' reviewThreads(first: 100) { nodes { isResolved isOutdated path comments(first: 1) { nodes { author { login } body url } } } }'
        + ' commits(last: 1) { nodes { commit { oid statusCheckRollup { state contexts(first: 50) { nodes { __typename'
        + ' ... on CheckRun { name status conclusion detailsUrl } ... on StatusContext { context state targetUrl } } } } } } }'
        + ' files(first: 100) { totalCount nodes { path additions deletions } } } }'
        + ' item: repository(owner: "Appmixer-ai", name: "' + target[1] + '") { issueOrPullRequest(number: ' + target[2] + ') {'
        + ' ... on Issue { comments(last: 100) { nodes { body } } } ... on PullRequest { comments(last: 100) { nodes { body } } } } }'
        + ' }';
    return {
        ok: true,
        prNumber: Number(pr),
        prUrl: d.pr_url,
        itemNodeId: d.item_node_id,
        projectNodeId: d.project_node_id,
        statusFieldId: d.status_field_id,
        target: d.target,
        query: JSON.stringify({ query })
    };
})())

// Every directory above a changed file under src/ may hold the bundle.json of its connector: read
// them all at the head of the PR, on its base branch and in the release (appmixer-components master)
// in one query.
JSON.stringify((function () {
    const parse = (x) => (typeof x === 'string' && x ? JSON.parse(x) : (x || null));
    const facts = parse($data.facts) || {};
    const p = (facts.data && facts.data.pr && facts.data.pr.pullRequest) || {};
    const files = ((p.files && p.files.nodes) || []).map((f) => f.path);
    const dirs = [];
    for (const f of files) {
        if (!/^src\/appmixer\//.test(f)) continue;
        const parts = f.split('/');
        for (let i = 3; i < parts.length; i++) {
            const dir = parts.slice(0, i).join('/');
            if (dirs.indexOf(dir) < 0) dirs.push(dir);
        }
    }
    const list = dirs.slice(0, 60);
    const sha = p.headRefOid || 'HEAD';
    const blob = (rev, path) => 'object(expression: "' + rev + ':' + path + '/bundle.json") { ... on Blob { text } }';
    const query = list.length
        ? 'query { head: repository(owner: "Appmixer-ai", name: "appmixer-connectors") { '
            + list.map((d, i) => 'h' + i + ': ' + blob(sha, d)).join(' ') + ' '
            + list.map((d, i) => 'b' + i + ': ' + blob(p.baseRefName || 'dev', d)).join(' ')
            + ' } release: repository(owner: "Appmixer-ai", name: "appmixer-components") { '
            + list.map((d, i) => 'r' + i + ': ' + blob('master', d)).join(' ') + ' } }'
        : 'query { viewer { login } }';
    return { dirs: list, query: JSON.stringify({ query }) };
})())

// The deterministic part of the Pre-release stage: one line per check, blocking or not, and the
// prompt for the design review.
JSON.stringify((function () {
    const parse = (x) => (typeof x === 'string' && x ? JSON.parse(x) : (x || null));

    const RENDER = function (state, lastRun) {
        const row = (r) => '- ' + String(r.at).slice(0, 16).replace('T', ' ') + ' UTC · ' + (r.from || '—') + ' → **' + r.to + '** (' + r.by + ')';
        const icon = { passed: '✅', failed: '❌', blocked: '⏸️', running: '⏳' };
        const stages = Object.keys(state.stages || {}).map((name) => {
            const s = state.stages[name];
            return ['', '### ' + name + ' ' + (icon[s.result] || '') + ' ' + s.result + ' · ' + String(s.at).slice(0, 16).replace('T', ' ') + ' UTC',
                '', s.summary || '', s.report ? '\n' + s.report : ''].join('\n');
        });
        // "--" never reaches the HTML comment, so a report cannot close the state block early
        const json = JSON.stringify(state).replace(/--/g, '\\u002d\\u002d');
        return [
            '🤖 **Pipeline** — status moves of this card on the ' + (state.organization || 'organization') + ' project board',
            '',
            state.runs.map(row).join('\n'),
            stages.join('\n'),
            '',
            'Connector: ' + (state.connector || '—') + ' · PR: ' + (state.pr || '—') + (lastRun ? ' · last run `' + lastRun + '`' : ''),
            '',
            '<!-- pipeline: ' + json + ' -->'
        ].join('\n');
    };
    const READ_STATE = function (comments) {
        const existing = (comments || []).filter((c) => typeof c.body === 'string' && c.body.indexOf('<!-- pipeline: ') >= 0)[0];
        let state = { runs: [], stages: {} };
        if (existing) {
            const m = existing.body.match(/<!-- pipeline: (\{[\s\S]*?\}) -->/);
            if (m) { try { state = JSON.parse(m[1]); } catch (e) { state = { runs: [], stages: {} }; } }
        }
        if (!Array.isArray(state.runs)) state.runs = [];
        if (!state.stages || typeof state.stages !== 'object') state.stages = {};
        return { existing, state };
    };

    const req = parse($data.request) || {};
    const facts = parse($data.facts) || {};
    const bundles = (parse($data.bundles) || {}).data || {};
    const dirs = (parse($data.dirs) || {}).dirs || [];
    const p = (facts.data && facts.data.pr && facts.data.pr.pullRequest) || {};
    const sha = p.headRefOid || '';
    const short = sha.slice(0, 7);
    const checks = [];
    const add = (ok, label, detail, blocking) => checks.push({ ok: !!ok, label, detail: detail || '', blocking: blocking !== false });

    // Pull request
    add(p.state === 'OPEN' && !p.isDraft, 'Pull request is open and ready for review', p.isDraft ? 'it is a draft' : (p.state !== 'OPEN' ? 'it is ' + p.state : ''));
    add(p.mergeable === 'MERGEABLE' && p.mergeStateStatus !== 'DIRTY', 'No merge conflicts with ' + (p.baseRefName || 'the base'), 'mergeable: ' + p.mergeable + ', state: ' + p.mergeStateStatus);
    add(p.mergeStateStatus !== 'BEHIND', 'Up to date with ' + (p.baseRefName || 'the base'), p.mergeStateStatus === 'BEHIND' ? 'the branch is behind — merge ' + p.baseRefName + ' into it before the merge' : '', false);
    const commit = (p.commits && p.commits.nodes && p.commits.nodes[0] && p.commits.nodes[0].commit) || {};
    const rollup = commit.statusCheckRollup || {};
    const runs = ((rollup.contexts && rollup.contexts.nodes) || []).filter((c) => c.__typename === 'CheckRun');
    const build = runs.filter((c) => c.name === 'build')[0];
    add(build && build.conclusion === 'SUCCESS', 'Node.js CI green on ' + short + ' (lint, validator, unit tests)', build ? (build.status + ' / ' + build.conclusion) : 'no build check on the head');
    const open = ((p.reviewThreads && p.reviewThreads.nodes) || []).filter((t) => !t.isResolved);
    add(!open.length, 'Every review thread resolved', open.length + ' open: ' + open.slice(0, 5).map((t) => {
        const c = (t.comments && t.comments.nodes && t.comments.nodes[0]) || {};
        return '[' + (t.path || 'thread') + '](' + (c.url || p.url) + ')';
    }).join(', '));
    const issueTarget = req.target && req.target.indexOf('Appmixer-ai/appmixer-connectors#') !== 0;
    if (issueTarget) {
        const closes = ((p.closingIssuesReferences && p.closingIssuesReferences.nodes) || [])
            .some((n) => n.repository.nameWithOwner + '#' + n.number === req.target);
        add(closes, 'The PR closes ' + req.target, closes ? '' : 'add "Fixes ' + req.target + '" to the description');
    }

    // Versions: the nearest bundle.json above each changed file
    const head = {};
    const base = {};
    const release = {};
    dirs.forEach((d, i) => {
        const h = bundles.head && bundles.head['h' + i];
        const r = bundles.release && bundles.release['r' + i];
        const b = bundles.head && bundles.head['b' + i];
        if (h && h.text) head[d] = h.text;
        if (b && b.text) base[d] = b.text;
        if (r && r.text) release[d] = r.text;
    });
    const files = ((p.files && p.files.nodes) || []).map((f) => f.path);
    const connectors = [];
    for (const f of files) {
        if (!/^src\/appmixer\//.test(f)) continue;
        let dir = f.split('/').slice(0, -1).join('/');
        while (dir.split('/').length > 2 && !head[dir]) dir = dir.split('/').slice(0, -1).join('/');
        if (head[dir] && connectors.indexOf(dir) < 0) connectors.push(dir);
    }
    const cmp = (a, b) => {
        const x = String(a).split('.').map(Number);
        const y = String(b).split('.').map(Number);
        for (let i = 0; i < 3; i++) { if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) - (y[i] || 0); }
        return 0;
    };
    for (const dir of connectors) {
        const name = dir.replace(/^src\/appmixer\//, '');
        let hb = {};
        let bb = null;
        let rb = null;
        try { hb = JSON.parse(head[dir]); } catch (e) { add(false, name + ': bundle.json', 'not valid JSON'); continue; }
        try { bb = base[dir] ? JSON.parse(base[dir]) : null; } catch (e) { bb = null; }
        try { rb = release[dir] ? JSON.parse(release[dir]) : null; } catch (e) { rb = null; }
        const log = hb.changelog || {};
        const hasEntry = Array.isArray(log[hb.version]) && log[hb.version].length > 0;
        add(hasEntry, name + ' ' + hb.version + ': changelog entry', hasEntry ? '' : 'no entry for ' + hb.version);
        if (bb) {
            // One bump per PR on top of the base branch, which may carry unreleased versions of other PRs
            const added = Object.keys(log).filter((k) => !(bb.changelog || {})[k]);
            add(cmp(hb.version, bb.version) > 0, name + ': version bumped over ' + (p.baseRefName || 'the base'), hb.version + ' here, ' + bb.version + ' on ' + p.baseRefName);
            add(added.length <= 1, name + ': one new version in the PR', added.length > 1 ? 'new entries ' + added.join(', ') + ' — fold them into one' : '');
        }
        if (rb) add(cmp(hb.version, rb.version) > 0, name + ': version above the release', hb.version + ' here, ' + rb.version + ' released');
        else add(true, name + ': not released yet', '', false);
    }
    if (!connectors.length) add(true, 'No connector changed', 'nothing to version', false);

    // Pipeline stages recorded on the item
    const comments = ((((facts.data || {}).item || {}).issueOrPullRequest || {}).comments || {}).nodes || [];
    const st = READ_STATE(comments).state;
    const testing = st.stages && st.stages.Testing;
    const testedHead = testing && /head ([0-9a-f]{7})/.exec(testing.summary || '');
    add(testing && testing.result === 'passed' && testedHead && testedHead[1] === short,
        'E2E report on the item: Testing passed on ' + short,
        !testing ? 'Testing never ran — move the card to Testing'
            : (testing.result !== 'passed' ? 'last Testing: ' + testing.result : (testedHead && testedHead[1] !== short ? 'passed on ' + testedHead[1] + ', the head is ' + short + ' — run Testing again' : '')));
    const docs = st.stages && st.stages['Doc&Verification'];
    const docsPr = docs && /https:\/\/github\.com\/Appmixer-ai\/appmixer-docs-gitbook\/pull\/\d+/.exec((docs.summary || '') + ' ' + (docs.report || ''));
    add(docs && (docs.result === 'passed' || docsPr), 'Documentation: app registration guide or its PR',
        !docs ? 'Doc&Verification never ran' : (docs.result === 'passed' ? (docsPr ? docsPr[0] : 'guide checked') : (docsPr ? 'docs PR ' + docsPr[0] + ' (open points: ' + String(docs.summary || '').slice(0, 160) + ')' : 'no docs PR')));

    const mandatoryOk = checks.every((c) => c.ok || !c.blocking);
    const changed = ((p.files && p.files.nodes) || []).map((f) => '- ' + f.path + ' (+' + f.additions + '/-' + f.deletions + ')').join('\n');
    const prompt = 'Review pull request #' + p.number + ' "' + p.title + '" of ' + 'Appmixer-ai/appmixer-connectors' + ' at commit ' + sha + '.\n'
        + 'Changed connectors: ' + (connectors.map((d) => d.replace(/^src\/appmixer\//, '')).join(', ') || 'none') + '.\n'
        + 'Changed files (' + (p.files ? p.files.totalCount : 0) + '):\n' + changed + '\n'
        + 'Raw URL of a file at this commit: https://raw.githubusercontent.com/Appmixer-ai/appmixer-connectors/' + sha + '/<path>';
    return { checks, mandatoryOk, prompt, prNumber: p.number, sha };
})())

// Joins the checklist and the review into the stage result for "CI - pipeline stage result".
JSON.stringify((function () {
    const parse = (x) => (typeof x === 'string' && x ? JSON.parse(x) : (x || null));
    const req = parse($data.request) || {};
    const list = parse($data.checklist) || {};
    const answer = String($data.answer || '');
    let review = null;
    const m = answer.match(/\{[\s\S]*\}/);
    if (m) { try { review = JSON.parse(m[0]); } catch (e) { review = null; } }
    const notes = review && Array.isArray(review.notes) ? review.notes.slice(0, 8).map(String) : [];
    const reviewOk = !!review && review.verdict === 'ok';
    const lines = (list.checks || []).map((c) => '- ' + (c.ok ? '✅' : (c.blocking ? '❌' : '⚠️')) + ' ' + c.label + (c.detail && !c.ok ? ' — ' + c.detail : ''));
    lines.push('- ' + (reviewOk ? '✅' : '❌') + ' Design review (Claude)' + (review ? '' : ' — the review did not answer in the expected format'));
    notes.forEach((n) => lines.push('    - ' + n));
    const failed = (list.checks || []).filter((c) => !c.ok && c.blocking).length + (reviewOk ? 0 : 1);
    const passed = list.mandatoryOk && reviewOk;
    return {
        stage: 'Pre-release',
        result: passed ? 'passed' : 'blocked',
        summary: passed ? 'Ready to merge: every check is green on ' + String(list.sha || '').slice(0, 7) + '.'
            : failed + ' item(s) missing before the release on ' + String(list.sha || '').slice(0, 7) + '.',
        report: lines.join('\n'),
        prUrl: req.prUrl,
        itemNodeId: req.itemNodeId,
        projectNodeId: req.projectNodeId,
        statusFieldId: req.statusFieldId,
        target: req.target,
        at: new Date().toISOString()
    };
})())
